import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{r as a,o as c,c as h,d as e,e as t,a as n,w as r,f as o}from"./app-36705845.js";const i={},l=o(`<h1 id="树-tree" tabindex="-1"><a class="header-anchor" href="#树-tree" aria-hidden="true">#</a> 树（Tree）</h1><p>树是一种非线性的数据结构，它是以分层的方式存储数据。树被用来存储具有层级关系的数据，比如文件系统中的目录、现实生活中的家谱、公司的组织架构，以及编译器里的语法树。</p><p>和数组、链表这类“排成一列”的结构不同，树里的每个元素通常只有一个前驱（父节点），却可以有零个或多个后继（子节点）。这种<strong>一对多</strong>的关系，让它特别适合表达嵌套、从属、分支这类结构。</p><h2 id="树的基本概念" tabindex="-1"><a class="header-anchor" href="#树的基本概念" aria-hidden="true">#</a> 树的基本概念</h2><p>一棵树由 <strong>节点（Node）</strong> 和连接节点的 <strong>边（Edge）</strong> 组成。下面是几个最常用的术语：</p><table><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td><strong>根节点（Root）</strong></td><td>树的顶端，整棵树只有一个节点是没有父节点的，这个节点就是根节点</td></tr><tr><td><strong>父节点 / 子节点</strong></td><td>若 A 在 B 的上一层且直接相连，则 A 是 B 的父节点，B 是 A 的子节点</td></tr><tr><td><strong>叶子节点（Leaf）</strong></td><td>没有子节点的节点</td></tr><tr><td><strong>子树（Subtree）</strong></td><td>以某个节点为根，包含其所有后代的树</td></tr><tr><td><strong>度（Degree）</strong></td><td>一个节点拥有的子节点个数；树中所有节点的最大度，称为树的度</td></tr><tr><td><strong>深度（Depth）</strong></td><td>从根到该节点所经过的边数；根节点深度为 0</td></tr><tr><td><strong>高度（Height）</strong></td><td>从该节点到其子树最远叶子所经过的边数；整棵树的高度即根节点的高度</td></tr></tbody></table><p>可以把树想象成倒置的组织架构图：老板在最上面是根，各级主管往下展开，最底层干活的员工往往是叶子节点。文件系统也类似：<code>/</code> 是根，<code>/home/user/docs</code> 是从根到某个文件的一条路径。</p><p><strong>路径</strong>是从一个节点到另一个节点所经过的节点序列；<strong>路径长度</strong>是路径上边的条数。树有一个重要性质：<strong>任意两个节点之间，路径唯一</strong>。不会出现图里那种“绕圈子”的情况——这也是树和图最根本的区别之一。</p><h2 id="多叉树的表示法" tabindex="-1"><a class="header-anchor" href="#多叉树的表示法" aria-hidden="true">#</a> 多叉树的表示法</h2><p>多叉树在内存里怎么存，取决于你更常做哪种操作：找父节点、找孩子、还是按层遍历。</p><h3 id="孩子链表-多叉树" tabindex="-1"><a class="header-anchor" href="#孩子链表-多叉树" aria-hidden="true">#</a> 孩子链表（多叉树）</h3><p>多叉树在代码里不好直接写“可变数量的指针”，经典做法是把<strong>任意多叉树转成二叉树</strong>： 每个节点保存一个指向<strong>第一个孩子</strong>的指针，同层兄弟再用链表串起来。这是表达多叉树最直接的方式，AST、文件系统目录树都常用类似思路。这种方式也被称为 <strong>左孩子右兄弟（Child-Sibling）</strong> 表示法。</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token keyword">struct</span> <span class="token class-name">TreeNode</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> value<span class="token punctuation">;</span>
    TreeNode<span class="token operator">*</span> first_child<span class="token punctuation">;</span>   <span class="token comment">// 第一个子节点</span>
    TreeNode<span class="token operator">*</span> next_sibling<span class="token punctuation">;</span>  <span class="token comment">// 右兄弟</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,13),g=o('<h3 id="数组表示-完全二叉树" tabindex="-1"><a class="header-anchor" href="#数组表示-完全二叉树" aria-hidden="true">#</a> 数组表示（完全二叉树）</h3><p>若一棵二叉树除了最后一层外都是满的，且最后一层从左到右连续，则称为<strong>完全二叉树</strong>。它可以用数组紧凑存储：下标 <code>i</code> 的左孩子在 <code>2i+1</code>，右孩子在 <code>2i+2</code>，父节点在 <code>(i-1)/2</code>。堆（优先队列的底层结构）就经常用这种表示。</p><h2 id="二叉树" tabindex="-1"><a class="header-anchor" href="#二叉树" aria-hidden="true">#</a> 二叉树</h2><p><strong>二叉树（Binary Tree）<strong>是每个节点最多有两个子节点的树，通常称为</strong>左子树</strong>和<strong>右子树</strong>。即使某个孩子为空，概念上的“左/右”位置仍然保留——左右是有区别的，不能简单当成“有两个可选槽位”。</p><p>几种特殊二叉树：</p><table><thead><tr><th>类型</th><th>特点</th></tr></thead><tbody><tr><td><strong>满二叉树</strong></td><td>每一层的节点数都达到该层能容纳的最大值</td></tr><tr><td><strong>完全二叉树</strong></td><td>除最后一层外满，最后一层从左到右填</td></tr><tr><td><strong>二叉搜索树（BST）</strong></td><td>左子树所有值 &lt; 根 &lt; 右子树所有值，中序遍历有序</td></tr><tr><td><strong>平衡二叉树</strong></td><td>左右子树高度差受限（如 AVL、红黑树），保证查找效率</td></tr></tbody></table><h2 id="树的遍历" tabindex="-1"><a class="header-anchor" href="#树的遍历" aria-hidden="true">#</a> 树的遍历</h2><p>遍历就是按某种顺序访问树中每个节点一次。二叉树最常见的遍历方式如下。</p><h3 id="深度优先遍历" tabindex="-1"><a class="header-anchor" href="#深度优先遍历" aria-hidden="true">#</a> 深度优先遍历</h3><p>沿着一条路径尽量走深，再回溯。对二叉树有三种经典顺序，区别只在于<strong>根节点何时被访问</strong>：</p><table><thead><tr><th>遍历</th><th>顺序</th><th>记忆</th></tr></thead><tbody><tr><td><strong>前序（Pre-order）</strong></td><td>根 → 左 → 右</td><td>先处理根</td></tr><tr><td><strong>中序（In-order）</strong></td><td>左 → 根 → 右</td><td>根在中间；BST 中序即升序</td></tr><tr><td><strong>后序（Post-order）</strong></td><td>左 → 右 → 根</td><td>根在最后；适合先处理子再处理父</td></tr></tbody></table>',11),p=e("strong",null,"栈",-1),u=e("strong",null,"递归",-1),E=o('<h3 id="广度优先遍历" tabindex="-1"><a class="header-anchor" href="#广度优先遍历" aria-hidden="true">#</a> 广度优先遍历</h3><p><strong>层序遍历（Level-order）<strong>从根开始，先访问同一层的所有节点，再访问下一层。实现上通常用</strong>队列</strong>：当前节点出队时，将其孩子按从左到右顺序入队。需要按层处理的问题（如打印每层节点、求树宽）很适合这种遍历。</p><h2 id="二叉搜索树" tabindex="-1"><a class="header-anchor" href="#二叉搜索树" aria-hidden="true">#</a> 二叉搜索树</h2><p><strong>二叉搜索树（Binary Search Tree，BST）</strong>，也叫<strong>排序二叉树</strong>：对任意节点，左子树所有键值小于该节点，右子树所有键值大于该节点（通常不允许重复；若允许，需约定放左还是放右）。</p><p>在理想情况下，查找、插入、删除的平均时间复杂度都是 <code>O(log n)</code>——每次比较都能排除大约一半的子树。但如果插入顺序恰好是有序的（如依次插入 1, 2, 3, …, n），BST 会退化为一根链，复杂度变成 <code>O(n)</code>。工程上会用 AVL 树、红黑树等<strong>自平衡</strong>结构来避免这种极端情况。</p><p>BST 的核心操作思路：</p><ul><li><strong>查找</strong>：从根出发，比根小走左，比根大走右，直到找到或走到空指针</li><li><strong>插入</strong>：按查找路径走到空位，在那里挂新节点</li><li><strong>删除</strong>：分三种情况——叶子直接删；只有一个孩子则用孩子顶替；有两个孩子则一般用中序后继（或前驱）替换再删后继</li></ul><h2 id="树在编译中的应用" tabindex="-1"><a class="header-anchor" href="#树在编译中的应用" aria-hidden="true">#</a> 树在编译中的应用</h2><p>树可能是编译原理里出现频率最高的数据结构之一。</p>',9),_=e("strong",null,"语法分析",-1),b=e("strong",null,[t("语法树（Parse Tree）"),e("strong",null,"或更精简的"),t("抽象语法树（AST）")],-1),B=e("p",null,[e("strong",null,"表达式"),t("天然是树形："),e("code",null,"1 + 2 * 3"),t(" 中，"),e("code",null,"*"),t(" 的优先级更高，在树里位置更低；"),e("code",null,"+"),t(" 在更高层把结果组合起来。语义分析、中间代码生成、优化，大多在这棵树上做遍历和改写。")],-1),f=e("strong",null,"控制流",-1),m=o('<p><strong>DOM树</strong>是编译器中分析Domination关系的重要数据结构。父亲节点可以支配子节点，意味着所有到达子节点的路径，都必须经过父亲节点。这样就可以帮助我们快速决定一个节点中的变量，会被哪些结点中的变量修改所影响。</p><h2 id="常见操作复杂度-参考" tabindex="-1"><a class="header-anchor" href="#常见操作复杂度-参考" aria-hidden="true">#</a> 常见操作复杂度（参考）</h2><table><thead><tr><th>操作</th><th>一般二叉树</th><th>二叉搜索树（平均）</th><th>二叉搜索树（最坏）</th></tr></thead><tbody><tr><td>查找</td><td><code>O(n)</code></td><td><code>O(log n)</code></td><td><code>O(n)</code></td></tr><tr><td>插入</td><td><code>O(1)</code>（已知父节点）</td><td><code>O(log n)</code></td><td><code>O(n)</code></td></tr><tr><td>删除</td><td><code>O(1)</code>（已知节点）</td><td><code>O(log n)</code></td><td><code>O(n)</code></td></tr><tr><td>遍历全部节点</td><td><code>O(n)</code></td><td><code>O(n)</code></td><td><code>O(n)</code></td></tr></tbody></table><p>这里的 <code>n</code> 是节点总数。实际选型时，除了复杂度，还要考虑是否需平衡、是否需顺序访问、内存布局是否友好等因素。</p><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结" aria-hidden="true">#</a> 小结</h2><p>树用<strong>分层、一对多</strong>的方式组织数据：有唯一的根，有清晰的路径，没有环。掌握基本术语、几种存储方式（孩子链表、左孩子右兄弟、数组堆式存储）以及遍历顺序（前/中/后序、层序），就能读懂大多数编译器前端和系统软件里的树形结构。更复杂的平衡树、B 树、Trie 等，都是在这一基础上为特定场景（查找、磁盘、字符串前缀）做的延伸。</p>',6);function A(x,k){const d=a("RouterLink");return c(),h("div",null,[l,e("p",null,[t("同一层的节点像链表一样挂在右指针上。LLVM、许多编译器 AST 都采用这种结构，详见 "),n(d,{to:"/LLVM%E6%8C%87%E5%8D%97/%E7%BC%96%E8%AF%91%E5%99%A8%E6%9E%B6%E6%9E%84%E7%9A%84%E7%8E%8B%E8%80%85LLVM%E2%80%94%E2%80%94%EF%BC%885%EF%BC%89%E8%AF%AD%E6%B3%95%E6%A0%91%E6%A8%A1%E5%9E%8B%E7%9A%84%E5%9F%BA%E6%9C%AC%E7%BB%93%E6%9E%84.html"},{default:r(()=>[t("语法树模型的基本结构")]),_:1}),t("。")]),g,e("p",null,[t("深度优先一般用"),p,t("或"),u,t("实现——递归本质上就是系统帮你维护了调用栈。这与 "),n(d,{to:"/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84/%E6%A0%88.html"},{default:r(()=>[t("栈")]),_:1}),t(" 一章里“深度遍历时栈的变化”是同一套机制。")]),E,e("p",null,[_,t("的结果往往是一棵"),b,t("。Flex 和 Bison 归约时，每个产生式对应一次“拼 subtree”；最终整份源程序被归约成开始符号那一棵大树。自顶向下分析从根开始展开，自底向上分析从叶子开始合并——详见 "),n(d,{to:"/%E7%BC%96%E8%AF%91%E5%8E%9F%E7%90%86/1.%E5%89%8D%E7%AB%AF/(2)%E8%AF%AD%E6%B3%95%E5%88%86%E6%9E%90.html"},{default:r(()=>[t("语法分析")]),_:1}),t("。")]),B,e("p",null,[f,t("也可以树化或图化：if-else、循环嵌套形成层次；更完整的跳转关系则用 "),n(d,{to:"/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84/%E5%9B%BE.html"},{default:r(()=>[t("图")]),_:1}),t(" 里的控制流图（CFG）表示——树擅长表达嵌套，图擅长表达跳转，二者经常配合使用。")]),m])}const O=s(i,[["render",A],["__file","树.html.vue"]]);export{O as default};
